// Serializes entries into a length-prefixed binary stream (monitor/archive-container.mjs packEntries).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { packEntries } from '../archive-container.mjs';

test('returns an empty buffer for an empty entry list', () => {
  assert.deepEqual(packEntries([]), Buffer.from("", 'hex'));
});

test('packs a single entry with a short path into the expected buffer', () => {
  const data = Buffer.from('hello');
  const entry = { path: 'a', data };
  assert.deepEqual(packEntries([entry]), Buffer.from("000000617b2270617468223a2261222c2273697a65223a352c22736861323536223a2232636632346462613566623061333065323665383362326163356239653239653162313631653563316661373432356537333034333336323933386239383234227d68656c6c6f", 'hex'));
});

test('packs a single entry with a long path into the expected buffer', () => {
  const data = Buffer.from('x'.repeat(100));
  const entry = { path: 'y'.repeat(50), data };
  assert.deepEqual(packEntries([entry]), Buffer.from("", 'hex'));
});

test('packs multiple entries in order into the expected buffer', () => {
  const entries = [
    { path: 'one', data: Buffer.from('first') },
    { path: 'two', data: Buffer.from('second') },
    { path: 'three', data: Buffer.from('third') }
  ];
  assert.deepEqual(packEntries(entries), Buffer.from("", 'hex'));
});

test('packs an entry with empty data into the expected buffer', () => {
  const entry = { path: 'empty', data: Buffer.alloc(0) };
  assert.deepEqual(packEntries([entry]), Buffer.from("000000657b2270617468223a22656d707479222c2273697a65223a302c22736861323536223a2265336230633434323938666331633134396166626634633839393666623932343237616534316534363439623933346361343935393931623738353262383535227d", 'hex'));
});

test('packs an entry with a unicode path into the expected buffer', () => {
  const data = Buffer.from('data');
  const entry = { path: 'file-123', data };
  assert.deepEqual(packEntries([entry]), Buffer.from("000000687b2270617468223a2266696c652d313233222c2273697a65223a342c22736861323536223a2233613665623037393066333961633837633934663338353662326464326335643131306536383131363032323631613961393233643362623233616463386237227d64617461", 'hex'));
});
